 function distribution(balances,owner=null,mode='type'){const rows=balances.filter(a=>!owner||a.owner===owner),groups=new Map();let unknown=0;for(const a of rows){if(!Number.isSafeInteger(a.cents)){unknown++;continue;}const type=group(a,mode),sum=(groups.get(type)||0)+a.cents;if(!Number.isSafeInteger(sum))throw Error('资产合计超出计算范围。');groups.set(type,sum);}const rank=t=>C.types.includes(t)?C.types.indexOf(t):C.types.length,parts=[...groups].map(([type,cents])=>({type,cents})).sort((a,b)=>mode==='currency'?a.type.localeCompare(b.type):rank(a.type)-rank(b.type)||a.type.localeCompare(b.type,'zh-CN'));const total=parts.reduce((n,p)=>n+p.cents,0);if(!Number.isSafeInteger(total))throw Error('资产合计超出计算范围。');return{parts,total,unknown,count:rows.length,hasNegative:parts.some(p=>p.cents<0)};}
