 const views=[panel('资产类型分布 · 成员与家庭','type',true),panel('币种分布 · 成员与家庭','currency',true),panel('家庭资产类型分布','type',false),panel('家庭币种分布','currency',false)];views.forEach((view,i)=>view.a.id=['asset-types','asset-currencies','overview-types','overview-currencies'][i]);$('unifiedAccounts').after(views[0].a,views[1].a);$('trend').after(views[2].a,views[3].a);
