 function details(view,box){if(view.selected===null)return;const rows=(D.balances||[]).filter(a=>(!view.owner||a.owner===view.owner)&&group(a,view.mode)===view.selected),section=document.createElement('section');section.className='asset-drilldown';const head=document.createElement('div');head.className='panel-head';const title=document.createElement('h3');title.textContent=name(view.owner)+' · '+view.selected+' · '+rows.length+'个账户';const close=document.createElement('button');close.className='outline';close.type='button';close.textContent='收起明细';close.onclick=()=>{view.selected=null;paint(view);};head.append(title,close);section.append(head);const scroll=document.createElement('div');scroll.className='table-scroll';const table=document.createElement('table'),thead=document.createElement('thead'),tr=document.createElement('tr'),tbody=document.createElement('tbody');for(const label of ['归属','类型','银行 / 平台 / 券商','账户','原币余额 / 市值','折合人民币','最近更新']){const th=document.createElement('th');th.textContent=label;tr.append(th);}thead.append(tr);for(const a of C.sorted(rows,D.memberProfiles||[])){const tr=document.createElement('tr');for(const value of [memberName(a.owner),a.typeDetail||C.normalize(a.type),a.institution||'—',a.name,nativeMoney(a.nativeCents,a.currency),money(a.cents),a.lastEventDate||a.confirmedDate||'待确认']){const td=document.createElement('td');td.textContent=value;tr.append(td);}tbody.append(tr);}table.append(thead,tbody);scroll.append(table);section.append(scroll);box.append(section);}
